import nltk  # Download required NLTK resources nltk.download('punkt') nltk.download('punkt_tab') nltk.download('averaged_perceptron_tagger_eng')  # Input sentence sentence = "The intelligent student solved the difficult problem quickly."  # Tokenize the sentence into words words = nltk.word_tokenize(sentence)  # Perform POS tagging pos_tags = nltk.pos_tag(words)  # Display the result print("Word\t\tPOS Tag") print("----------------------")  for word, tag in pos_tags:     print(f"{word:<15} {tag}")   